import requests
for endpoint,params in [('https://api.crossref.org/works',{'query.title':'genomic prediction maritime pine generations','rows':15}),('https://api.openalex.org/works',{'search':'genomic prediction maritime pine generations','per-page':15})]:
 r=requests.get(endpoint,params=params,timeout=25)
 print('\n',endpoint,r.status_code)
 if 'crossref' in endpoint:
  for x in r.json()['message']['items']:
   print(x.get('title',[''])[0],x.get('author',[{}])[0].get('family'),x.get('published',{}).get('date-parts'),x.get('DOI'))
 else:
  for x in r.json().get('results',[]): print(x.get('title'),x.get('publication_year'),x.get('doi'),x.get('authorships',[{}])[0].get('author',{}).get('display_name'))
